	"# scalpel-lib.janet — pure-Janet helpers over the pg_scalpel primitives.\n"
	"# This is the SOURCE of the extension's auto-loaded prelude: tools/embed-prelude.janet\n"
	"# bakes it into ext/pgs_prelude.h at build time, and pgs_vm_ensure evaluates it at\n"
	"# VM init, so make-struct/pack-struct/read-struct are present in every REPL with no\n"
	"# manual load. (After editing this file you must rebuild; to hot-reload without a\n"
	"# rebuild during dev, (eval-string (slurp \".../janet-lib/scalpel-lib.janet\")).)\n"
	"#\n"
	"# Turns a (scalpel/struct ...) layout into a ready struct-by-pointer buffer (and back).\n"
	"# Scalar fields only; pointer/cstring/datum fields take an integer address\n"
	"# (0 = NULL). Janet numbers are f64, so values/addresses above 2^53 lose precision.\n"
	"\n"
	"(defn- enc-field\n"
	"  \"Encode one scalar field value to a little-endian buffer per its :call keyword.\"\n"
	"  [call value]\n"
	"  (def b (buffer/new 8))\n"
	"  (case call\n"
	"    :int     (buffer/push-uint32 b :le (if (< value 0) (+ value 0x100000000) value))\n"
	"    :uint    (buffer/push-uint32 b :le value)\n"
	"    :int64   (buffer/push-uint64 b :le value)\n"
	"    :uint64  (buffer/push-uint64 b :le value)\n"
	"    :datum   (buffer/push-uint64 b :le value)\n"
	"    :pointer (buffer/push-uint64 b :le value)\n"
	"    :cstring (buffer/push-uint64 b :le value)\n"
	"    :bool    (buffer/push-byte   b (if value 1 0))\n"
	"    :double  (buffer/push-float64 b :le value)\n"
	"    :float   (buffer/push-float32 b :le value)\n"
	"    (errorf \"pack-struct: unhandled field call-type %p (set this field manually)\" call))\n"
	"  b)\n"
	"\n"
	"(defn pack-struct\n"
	"  ``Build a byte buffer for a struct LAYOUT (as returned by scalpel/struct), writing\n"
	"  each field named in VALUES (name -> value) at its :offset. Unset fields stay\n"
	"  zero. Returns a buffer you can pass to scalpel/call as a :bytes argument.``\n"
	"  [layout values]\n"
	"  (def buf (buffer/new-filled (layout :size)))\n"
	"  (each f (layout :fields)\n"
	"    (def v (get values (f :name)))\n"
	"    (when (not= v nil)\n"
	"      (buffer/blit buf (enc-field (f :call) v) (f :offset))))\n"
	"  buf)\n"
	"\n"
	"(defn make-struct\n"
	"  \"Resolve struct NAME via scalpel/struct and pack VALUES into a fresh buffer.\"\n"
	"  [name values]\n"
	"  (def layout (scalpel/struct name))\n"
	"  (unless layout (errorf \"make-struct: unknown struct %s\" name))\n"
	"  (pack-struct layout values))\n"
	"\n"
	"(defn- dec-uint [buf off n]\n"
	"  # multiply/add (not bit-shift): Janet bit ops are 32-bit; this stays in the\n"
	"  # float domain (exact up to 2^53, so 4-byte and pointer-sized reads are exact)\n"
	"  (var acc 0)\n"
	"  (var mul 1)\n"
	"  (for i 0 n\n"
	"    (+= acc (* (in buf (+ off i)) mul))\n"
	"    (set mul (* mul 256)))\n"
	"  acc)\n"
	"\n"
	"(defn read-struct\n"
	"  ``Read integer/pointer/bool fields out of BUF per LAYOUT into a name->value\n"
	"  table (e.g. to inspect an output struct a call filled in). float/double and\n"
	"  aggregate fields are skipped.``\n"
	"  [layout buf]\n"
	"  (def out @{})\n"
	"  (each f (layout :fields)\n"
	"    (def o (f :offset))\n"
	"    (def v\n"
	"      (case (f :call)\n"
	"        :int     (let [u (dec-uint buf o 4)]\n"
	"                   (if (>= u 0x80000000) (- u 0x100000000) u))\n"
	"        :uint    (dec-uint buf o 4)\n"
	"        :int64   (dec-uint buf o 8)\n"
	"        :uint64  (dec-uint buf o 8)\n"
	"        :datum   (dec-uint buf o 8)\n"
	"        :pointer (dec-uint buf o 8)\n"
	"        :cstring (dec-uint buf o 8)\n"
	"        :bool    (not= 0 (in buf o))\n"
	"        nil))\n"
	"    (when (not= v nil) (put out (f :name) v)))\n"
	"  out)\n"
	"\n"
	"# ---- script loader -------------------------------------------------------\n"
	"# scalpel-load resolves script paths relative to this root (default:\n"
	"# $HOME/pg_scalpel) so you can pull in example/instrument scripts by short name\n"
	"# after connecting. Override by redefining scalpel-root if your checkout is elsewhere.\n"
	"(def scalpel-root (string (os/getenv \"HOME\") \"/pg_scalpel\"))\n"
	"\n"
	"(defn scalpel-load\n"
	"  ``Load a Janet script by path relative to scalpel-root ('.janet' optional) and\n"
	"  return its final value. E.g. (scalpel-load \"janet-lib/fuzz\") loads the fuzz engine;\n"
	"  (def t (scalpel-load \"fuzz/targets/numeric\")) loads a target and captures its table.``\n"
	"  [relpath]\n"
	"  (def p (if (string/has-suffix? \".janet\" relpath) relpath (string relpath \".janet\")))\n"
	"  (eval-string (slurp (string scalpel-root \"/\" p))))\n"
	"\n"
	":scalpel-lib-loaded\n"
	"\n"
	"# patch.janet — live function hot-patching via inline detour.\n"
	"#   (scalpel-load \"janet-lib/patch\")\n"
	"#\n"
	"# Built on scalpel/resolve + scalpel/call + scalpel/page-protect + scalpel/flush-icache.\n"
	"# Overwrites a target function's prologue with a 14-byte absolute jump to a\n"
	"# replacement, so EVERY caller (fmgr dispatch or a hard-linked C call) is\n"
	"# rerouted. Process-local and copy-on-write: only THIS backend is affected, and\n"
	"# the change dies with it.\n"
	"#\n"
	"#   (def P (scalpel-load \"janet-lib/patch\"))\n"
	"#   (def h (patch-jump \"int4pl\" \"int4mi\"))   # reroute int4pl -> int4mi\n"
	"#   ...exercise it from SQL in the SAME session...\n"
	"#   (unpatch h)                              # restore the original bytes\n"
	"#\n"
	"# WARNING: superuser/instrument-only. Patching a function that is currently on\n"
	"# the call stack is racy (the in-flight call finishes as the original).\n"
	"# Inlined/optimized-away functions have no single body to patch.\n"
	"\n"
	"(defn ptr->int\n"
	"  \"Numeric address of a pointer abstract (resolve returns these, not numbers).\"\n"
	"  [p]\n"
	"  (let [s (string/format \"%q\" p)\n"
	"        i (string/find \"0x\" s)\n"
	"        e (string/find \">\" s)]\n"
	"    (when (and i e) (scan-number (string/slice s i e)))))\n"
	"\n"
	"(defn- addr-of [x]\n"
	"  # accept a symbol name (string), a raw address (number), or a pointer abstract\n"
	"  (cond\n"
	"    (string? x) (or (ptr->int (scalpel/resolve x)) (errorf \"patch: cannot resolve %s\" x))\n"
	"    (number? x) x\n"
	"    (or (ptr->int x) (errorf \"patch: not an address: %q\" x))))\n"
	"\n"
	"(defn peek-bytes\n"
	"  \"Read N bytes from address ADDR into a fresh buffer (via memcpy).\"\n"
	"  [addr n]\n"
	"  (def buf (buffer/new-filled n))\n"
	"  (scalpel/call-raw (scalpel/resolve \"memcpy\") :pointer [:bytes :pointer :uint64] buf (addr-of addr) n)\n"
	"  buf)\n"
	"\n"
	"(defn poke-bytes\n"
	"  ``Write BYTES into address ADDR: flip the page writable+executable, copy,\n"
	"  flush the instruction cache, then restore read+execute protection. The\n"
	"  page-protect calls ERROR (not silently) if mprotect fails, so we never poke a\n"
	"  read-only page (the guard catches the PG ereport).``\n"
	"  [addr bytes]\n"
	"  (def a (addr-of addr))\n"
	"  (def n (length bytes))\n"
	"  (scalpel/page-protect a n true)            # RWX (page-aligned in C)\n"
	"  (scalpel/call-raw (scalpel/resolve \"memcpy\") :pointer [:pointer :bytes :uint64] a bytes n)\n"
	"  (scalpel/flush-icache a n)\n"
	"  (scalpel/page-protect a n false)           # restore R-X\n"
	"  a)\n"
	"\n"
	"(defn abs-jmp-bytes\n"
	"  \"14-byte position-independent absolute jump to DEST: FF 25 00000000 <abs64 LE>.\"\n"
	"  [dest]\n"
	"  (def s (buffer/new 14))\n"
	"  (buffer/push-byte s 0xFF)\n"
	"  (buffer/push-byte s 0x25)\n"
	"  (buffer/push-uint32 s :le 0)\n"
	"  (buffer/push-uint64 s :le dest)\n"
	"  s)\n"
	"\n"
	"(defn install\n"
	"  ``Core primitive: overwrite TARGET (name/address/pointer) with STUB bytes,\n"
	"  saving exactly (length STUB) original bytes. Returns a handle for unpatch.\n"
	"  Pure replacement — STUB must be self-contained (we never run the original).\n"
	"\n"
	"  The overwrite is NOT atomic (a plain memcpy of the prologue). This is safe\n"
	"  only because it is process-local and single-threaded: a Postgres backend is\n"
	"  one thread, so no other thread can observe a half-written prologue, and COW\n"
	"  means no other backend sees the write at all. Patching a function currently on\n"
	"  the call stack is still racy — the in-flight call finishes as the original.``\n"
	"  [target stub]\n"
	"  (def a (addr-of target))\n"
	"  (def n (length stub))\n"
	"  (def orig (peek-bytes a n))            # save before we clobber\n"
	"  (poke-bytes a stub)\n"
	"  {:addr a :len n :orig orig})\n"
	"\n"
	"(defn patch-jump\n"
	"  ``Reroute TARGET to DEST via an absolute jump (each a name/address/pointer).\n"
	"  Use when DEST is a real function with a matching ABI (e.g. int4pl->int4mi).``\n"
	"  [target dest]\n"
	"  (def d (addr-of dest))\n"
	"  (merge (install target (abs-jmp-bytes d)) {:to d}))\n"
	"\n"
	"# ---- Way 1: Janet-generated replacement stubs (no bytes supplied by hand) ----\n"
	"\n"
	"(defn ret-int-bytes\n"
	"  \"mov eax, N ; ret  (B8 <imm32 LE> C3) — return the int4/Datum constant N in RAX.\"\n"
	"  [n]\n"
	"  (def v (if (< n 0) (+ n 0x100000000) n))\n"
	"  (def s (buffer/new 6))\n"
	"  (buffer/push-byte s 0xB8)\n"
	"  (buffer/push-uint32 s :le v)\n"
	"  (buffer/push-byte s 0xC3)\n"
	"  s)\n"
	"\n"
	"(defn patch-return-int\n"
	"  ``Force TARGET (an fmgr/int4-returning C function) to ignore its arguments and\n"
	"  always return the int4 constant N. The classic fault-injection stub — Janet\n"
	"  builds the machine code from N; you never touch bytes. Returns a handle.``\n"
	"  [target n]\n"
	"  (merge (install target (ret-int-bytes n)) {:returns n}))\n"
	"\n"
	"(defn patch-return-zero\n"
	"  \"xor eax,eax ; ret (31 C0 C3) — force TARGET to return 0 / false / NULL-datum.\"\n"
	"  [target]\n"
	"  (def s (buffer/new 3))\n"
	"  (buffer/push-byte s 0x31) (buffer/push-byte s 0xC0) (buffer/push-byte s 0xC3)\n"
	"  (install target s))\n"
	"\n"
	"(defn unpatch\n"
	"  \"Restore the original bytes saved in a patch handle (jump or stub).\"\n"
	"  [h]\n"
	"  (poke-bytes (h :addr) (h :orig))\n"
	"  (h :addr))\n"
	"\n"
	"# ---- inline hooking with a trampoline (call the original) ----\n"
	"# Backed by scalpel/hook (funchook). TARGET may be a name/address/pointer; DETOUR is\n"
	"# a code pointer (e.g. from scalpel/closure). Returns the trampoline pointer — call\n"
	"# it with TARGET's signature to run the original function.\n"
	"\n"
	"(defn hook\n"
	"  ``Detour TARGET to DETOUR; returns the trampoline pointer to reach the original.``\n"
	"  [target detour]\n"
	"  (scalpel/hook (addr-of target) detour))\n"
	"\n"
	"(defn unhook\n"
	"  \"Remove a hook installed on TARGET (name/address/pointer).\"\n"
	"  [target]\n"
	"  (scalpel/unhook (addr-of target)))\n"
	"\n"
	"# ---- pure replacement: original is never called ----\n"
	"# replace-fn detours TARGET to a Janet function with the matching ABI. The Janet\n"
	"# function IS the function now — the original bytes become unreachable for the\n"
	"# duration of the hook. Use when you want to write the body in Janet rather than\n"
	"# wrap the existing body. RET-TYPE + ARG-TYPES describe the signature exactly\n"
	"# like scalpel/closure. For fmgr functions, arg-types is [:pointer] (fcinfo) and the\n"
	"# body reads args via (scalpel/getarg fcinfo n type).\n"
	"#\n"
	"#   (replace-fn \"int4pl\" :int [:pointer]\n"
	"#     (fn [fcinfo]\n"
	"#       (def a (scalpel/getarg fcinfo 0 :int))\n"
	"#       (def b (scalpel/getarg fcinfo 1 :int))\n"
	"#       (- a b)))                       # '+' is '-' now, body written in Janet\n"
	"\n"
	"(defn replace-fn\n"
	"  ``Replace TARGET entirely with FN (a Janet function). The original is never\n"
	"  called — the detour does not call back through the trampoline. Returns a\n"
	"  handle ({:addr :detour}); remove with (unhook target).``\n"
	"  [target ret-type arg-types fn]\n"
	"  (def a (addr-of target))\n"
	"  (def detour (scalpel/closure ret-type arg-types fn))\n"
	"  (scalpel/hook a detour)                  # trampoline returned but discarded\n"
	"  {:addr a :detour detour})\n"
	"\n"
	"# ---- ergonomic onEnter/onLeave wrapping (Frida Interceptor.attach) ----\n"
	"# hook-fn wraps TARGET so it still runs (via the trampoline) but you observe its\n"
	"# args on entry and observe/replace its return on leave. RET-TYPE + ARG-TYPES\n"
	"# describe the signature exactly like scalpel/closure / scalpel/call.\n"
	"#   :on-enter (fn [args])        observe the arg array (marshalled Janet values)\n"
	"#   :on-leave (fn [args ret] ->) the value you return REPLACES the result;\n"
	"#                                return ret unchanged to pass through.\n"
	"\n"
	"(defn hook-fn\n"
	"  ``Wrap TARGET with onEnter/onLeave around a real call to the original.\n"
	"  Returns a handle ({:addr :detour}); remove with (unhook target).``\n"
	"  [target ret-type arg-types &named on-enter on-leave]\n"
	"  (def a (addr-of target))\n"
	"  (def cell @{:tramp nil})\n"
	"  (def detour\n"
	"    (scalpel/closure ret-type arg-types\n"
	"      (fn [& args]\n"
	"        (when on-enter (on-enter args))\n"
	"        (def r (scalpel/call (cell :tramp) ret-type arg-types ;args))\n"
	"        (cond\n"
	"          (not (indexed? r)) r\n"
	"          (= (get r 0) :ok)  (let [ret (get r 1)]\n"
	"                               (if on-leave (on-leave args ret) ret))\n"
	"          # original raised: re-propagate (closure dispatcher -> ereport)\n"
	"          (error (get r 1))))))\n"
	"  (put cell :tramp (scalpel/hook a detour))\n"
	"  {:addr a :detour detour})\n"
	"\n"
	"# ---- trace (frida-trace): hook a family of same-signature functions ----\n"
	"# trace-log accumulates @{:fn :args :ret} records. You MUST pass the signature\n"
	"# (ret-type arg-types) — every matched function is called through it, so the sig\n"
	"# must be correct for all of them (e.g. fmgr functions are all :datum [:pointer]).\n"
	"\n"
	"(def trace-log @[])\n"
	"(defn trace-clear [] (array/clear trace-log))\n"
	"\n"
	"(defn trace\n"
	"  ``Hook every symbol matching PATTERN (scalpel/syms wildcard) with the GIVEN\n"
	"  signature and log each call to trace-log. :stack true also records a\n"
	"  backtrace per call. Returns a handle for untrace. NOTE: the signature is\n"
	"  applied to every match — only trace functions that truly share it.``\n"
	"  [pattern ret-type arg-types &named limit stack]\n"
	"  (default limit 50)\n"
	"  (def hooked @[])\n"
	"  (each s (scalpel/syms pattern limit)\n"
	"    (def nm (s :name))\n"
	"    (when (try\n"
	"            (do (hook-fn nm ret-type arg-types\n"
	"                  :on-leave (fn [args ret]\n"
	"                              (array/push trace-log\n"
	"                                @{:fn nm :args args :ret ret\n"
	"                                  :stack (if stack (scalpel/backtrace 12) nil)})\n"
	"                              ret))\n"
	"                true)\n"
	"            ([_] false))\n"
	"      (array/push hooked nm)))\n"
	"  {:pattern pattern :hooked hooked})\n"
	"\n"
	"(defn untrace\n"
	"  \"Remove all hooks installed by a trace handle.\"\n"
	"  [h]\n"
	"  (each nm (h :hooked) (try (scalpel/unhook (addr-of nm)) ([_] nil)))\n"
	"  (length (h :hooked)))\n"
	"\n"
	":patch-lib-loaded\n"
	"\n"
	;
